package org.unicog.numberrace.ui;
import java.awt.*;import javax.swing.*;import javax.swing.plaf.basic.BasicButtonUI;
public class GameButton extends BasicButtonUI {public void paint(Graphics g,JComponent c){JButton b=(JButton)c;Graphics2D p=GameTheme.graphics(g);Color base=b.isEnabled()?b.getBackground():new Color(207,216,225);if(b.getModel().isPressed())base=base.darker();else if(b.getModel().isRollover())base=base.brighter();GameTheme.surface(p,c.getWidth(),c.getHeight(),base.brighter(),base,24);if(b.hasFocus()){p.setColor(GameTheme.INK);p.setStroke(new BasicStroke(2));p.drawRoundRect(5,5,c.getWidth()-11,c.getHeight()-15,18,18);}p.dispose();super.paint(g,c);} protected void paintText(Graphics g,AbstractButton b,Rectangle r,String text){g.setColor(b.isEnabled()?b.getForeground():new Color(74,87,99));g.setFont(b.getFont());g.drawString(text,r.x,r.y+g.getFontMetrics().getAscent());}}